using static CampusFix.Api.Services.J;
namespace CampusFix.Api.Services;
public partial class CampusService {
 byte[] MailKey(){var secret=configuration["Mail:EncryptionKey"];Require(secret?.Length>=32,503,"Configura Mail:EncryptionKey con al menos 32 caracteres.");return SHA256.HashData(Encoding.UTF8.GetBytes(secret!));}
 async Task<object> MailApi(string path,string method,JsonObject b){var m=await s.Get("settings","mail");if(path=="mail"&&method=="GET")return new{configured=m!=null&&!m.B("eliminado"),version=m.I("_v"),from=m.B("eliminado")?"":m.S("from"),tested=!m.B("eliminado")&&m.B("tested"),enabled=!m.B("eliminado")&&m.B("enabled"),queue=(await s.All("mail")).OrderByDescending(j=>j.S("created")).Take(100)};
  if(path=="mail"&&method=="DELETE"){Require(m!=null&&!m.B("eliminado"),404,"Conexión no encontrada.");Require(b.ContainsKey("version"),409,"Actualiza la conexión antes de eliminarla.");Version(m,b);Require(!m.B("enabled"),409,"Desactiva la conexión antes de retirarla.");Require(!(await s.All("mail")).Any(j=>j.S("status") is "pending" or "retry"),409,"Hay envíos pendientes. Resuélvelos antes de retirar la conexión.");MarkDeleted(m);await s.Save("settings",m);await Audit("Conexión de correo eliminada lógicamente","mail");return new{ok=true};}
  if(path=="mail"&&method=="PUT"){if(m!=null&&m.B("eliminado")){var history=m.Copy();history["id"]=Id();history["_v"]=0;await s.Save("settingsHistory",history);}var from=Email(b,"from");var key=Required(b,"key","Clave de Resend",300);var iv=RandomNumberGenerator.GetBytes(12);var plain=Encoding.UTF8.GetBytes(key);var cipher=new byte[plain.Length];var tag=new byte[16];using(var aes=new AesGcm(MailKey(),16))aes.Encrypt(iv,plain,cipher,tag);await s.Save("settings",Merge(m??new(),Obj(new{id="mail",from,iv=Convert.ToBase64String(iv),secret=Convert.ToBase64String(cipher),tag=Convert.ToBase64String(tag),tested=false,enabled=false,eliminado=false,fechaEliminacion=(string?)null,eliminadoPorId=(string?)null})));await Audit("Conexión de correo actualizada","mail");return new{ok=true};}
  Require(m!=null&&!m.B("eliminado"),400,"Configura primero la conexión.");var encrypted=Convert.FromBase64String(m!.S("secret"));var bytes=new byte[encrypted.Length];using(var aes=new AesGcm(MailKey(),16))aes.Decrypt(Convert.FromBase64String(m.S("iv")),encrypted,Convert.FromBase64String(m.S("tag")),bytes);var token=Encoding.UTF8.GetString(bytes);
  async Task<JsonObject> Send(string to,string title,string id){using var req=new HttpRequestMessage(HttpMethod.Post,"https://api.resend.com/emails");req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);req.Headers.Add("Idempotency-Key",id);req.Content=JsonContent.Create(new{from=m.S("from"),to=new[]{to},subject="CampusFix · "+title,text=title+"\nIngresa a CampusFix para consultar el detalle."});using var response=await clients.CreateClient("mail").SendAsync(req);if(!response.IsSuccessStatusCode)throw new ApiError(400,$"El proveedor rechazó el envío ({(int)response.StatusCode}).");return JsonNode.Parse(await response.Content.ReadAsStringAsync())!.AsObject();}
  if(path=="mail/test"&&method=="POST"){await Send(u.S("correo"),"Prueba de conexión",Id());m["tested"]=true;await s.Save("settings",m);return new{ok=true};}
  if(path=="mail/activate"&&method=="POST"){Require(!b.B("enabled")||m.B("tested"),400,"Prueba la conexión antes de activarla.");m["enabled"]=b.B("enabled");await s.Save("settings",m);return new{ok=true};}
  if(path=="mail/process"&&method=="POST"){Require(m.B("enabled"),400,"El correo está desactivado.");foreach(var job in (await s.All("mail")).Where(j=>j.S("status") is "pending" or "retry"&&Date(j.S("next"))<=DateTimeOffset.UtcNow).Take(10)){if(DateTimeOffset.UtcNow-Date(job.S("created"))>TimeSpan.FromHours(23)){job["status"]="review";await s.Save("mail",job);continue;}var n=job.I("attempts")+1;try{var result=await Send(job.S("to"),job.S("title"),job.S("id"));job["status"]="accepted";job["providerId"]=result.S("id");}catch(Exception e) when(e is HttpRequestException or TaskCanceledException or ApiError){job["status"]=n>=4?"failed":"retry";job["error"]=e is ApiError?e.Message:"No se pudo contactar al proveedor.";job["next"]=DateTimeOffset.UtcNow.AddMinutes(Math.Pow(2,n)).ToString("O");}job["attempts"]=n;await s.Save("mail",job);}return new{ok=true};}throw new ApiError(404,"Ruta no encontrada.");
 }
